    fprintf(stderr, "put_bit(%d, %d) - range=%ld, low=%ld\n", bit, ctx, range_val, low_val);

    // Emit bytes if range gets too small
    while (range_val < radix) {
        int byte_val = (low_val / range_val) % radix + 1;
        emit_byte(byte_val);
        low_val = low_val % range_val;
        low_val *= radix;
        range_val *= radix;
    }

    int *counts = cc + ctx * 2;
    long split = range_val * (counts[0] + 1) / (counts[0] + counts[1] + 2);

    if (bit) {
        low_val += split;
        range_val -= split;
    } else {
        range_val = split;
    }

    counts[bit]++;
}

void put_integer(int value, int size_bits, int ctx) {
    fprintf(stderr, "put_integer(%d, %d, %d)\n", value, size_bits, ctx);

    int subtract_it = 1 << size_bits;
    value += subtract_it;

    fprintf(stderr, "  After adding offset: %d\n", value);

    // Find number of bits needed
    int nbits = 0;
    int temp = value;
    while (temp > 0) {
        nbits++;
        temp >>= 1;
    }

    fprintf(stderr, "  nbits = %d\n", nbits);

    ctx *= 99;
    // Emit unary: nbits zeros then a one
    for (int i = 0; i < nbits; i++) {
        put_bit(0, size_bits + 1 + i + ctx);
    }
    put_bit(1, size_bits + 1 + nbits + ctx);

    // Emit the value in binary
    for (int i = nbits - 1; i >= 0; i--) {
        put_bit((value >> i) & 1, ctx);
    }
}

void flush_encoder() {
    fprintf(stderr, "Flushing encoder\n");
    for (int i = 0; i < 10; i++) {
        emit_byte((low_val / range_val) % radix + 1);
    }
}

